#!/usr/bin/env node
// Copies the fine-tune body-word blocklists into worker/src/blocklist.generated.ts,
// so the Worker can count voice slips with the same lists the eval uses.
// Run from anywhere: node worker/scripts/gen-blocklist.mjs
// The source of truth stays in finetune/filters. Never edit the generated file.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const filters = resolve(here, "../../finetune/filters");
const out = resolve(here, "../src/blocklist.generated.ts");

/** Same rule as finetune/filter.py: trimmed lines, no blanks, no # comments. */
const load = (name) =>
  readFileSync(resolve(filters, name), "utf8")
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith("#"));

const en = load("blocklist_en.txt");
const ar = load("blocklist_ar.txt");

const body = `// GENERATED by worker/scripts/gen-blocklist.mjs from finetune/filters/blocklist_{en,ar}.txt.
// Do not edit. Rerun the script when the lists change. A test checks they match.

export const BLOCKLIST_EN: readonly string[] = ${JSON.stringify(en, null, 2)};

export const BLOCKLIST_AR: readonly string[] = ${JSON.stringify(ar, null, 2)};
`;

writeFileSync(out, body);
console.log(`wrote ${out}: ${en.length} en, ${ar.length} ar entries`);
